  Future<void> _applyConfig(MemoryConfig next) async {
    _activeConfig = next;
    _projectStoragePath = next.projectPath;
    _userStoragePath = next.userPath;
    _projectStorage = null;
    _projectStore = null;
    _projectSearch = null;
    _userStorage = null;
    _userStore = null;
    _userSearch = null;
    onConfigChanged?.call();
